// The `_$TodoWindowTemplate` mixin is generated by
// `gtk_templates_builder` (see `build.yaml`); running
// `dart run build_runner build` (or `dart run
// gtk_templates_builder lib/todo_window.dart`) writes
// `lib/todo_window.g.dart` next to this file.
//
// The generated file is a `part of 'todo_window.dart'`, so
// it shares this library's imports and the trampoline can
// resolve the user's instance method names at compile time.
// The mixin provides the `counterLabel` and `button` fields
// as `late final`s and wires the
// `<signal name="clicked" handler="on_clicked"/>` to our
// `onClicked()` method via the per-instance `connectSignal`
// trampoline.
//
// The part file name is derived from this file's name alone
// (`todo_window.dart` → `todo_window.g.dart`), the same
// convention `json_serializable` uses — one part file per
// source file, holding the mixins of every annotated class.
//
// Two things about the XML are worth knowing:
//
//   * The `<template class="…" parent="…">` attributes are advisory.
//     A Dart subclass has no GType of its own, so the generated
//     mixin rewrites them to the instance's real native type before
//     GTK sees them — GTK checks both and rejects a mismatch.
//   * The `<signal name="clicked" handler="on_clicked"/>` element is
//     read by the *builder* (it tells the codegen what to wire) and
//     removed before GTK sees the XML: GtkBuilder would look
//     `on_clicked` up as a C symbol, which a Dart class cannot
//     provide. The mixin wires the signal with a Dart closure
//     instead.

import 'package:adw/adw.dart';
import 'package:gtk4/gtk4.dart';
import 'package:gtk_templates/gtk_templates.dart';

part 'todo_window.g.dart';

@GtkTemplate(source: GtkTemplateFile('data/window.ui'))
class TodoWindow extends AdwApplicationWindow with _$TodoWindowTemplate {
  TodoWindow(super.app) {
    // GTK builds a widget's template in the instance initializer.
    // Dart has no instance-initializer hook, so the generated mixin
    // exposes `initTemplate()` and the widget calls it from its
    // constructor. Without this call the window stays empty: the
    // template is only built lazily, on the first read of a
    // generated field.
    initTemplate();
  }

  int _clicks = 0;

  // Auto-wired by the generated mixin via
  // `button.onClicked(() => onClicked())`. The method name
  // is the XML's `handler="on_clicked"` converted to
  // `lowerCamelCase`; the arity must match the
  // GIR-declared `clicked` signal on `GtkButton`
  // (`void Function()`).
  void onClicked() {
    _clicks += 1;
    counterLabel.props.label = 'Clicked $_clicks times';
  }
}
